INSERT INTO public.sys_config (id, config_key, config_value, category, remark, sort_code, ext_json, created_at, created_by, updated_at, updated_by, value_type, label, scope, scene, is_builtin) VALUES ('cfg_mail_acct_cancel_01', 'MAIL_TEMPLATE_ACCOUNT_CANCELLED', '{"subject": "{{app_name}} 账号注销确认", "body": "您好，您的账号已申请注销。\n\n我们将在 {{retention_days}} 天内保留账号数据；到期且期间未再登录使用后，系统将彻底删除账号及相关数据。\n\n预计清理时间：{{purge_at}}\n如非本人操作，请尽快联系管理员。"}', 'MAIL_TEMPLATE', '账号注销确认邮件模板', 20, '{}', '2026-08-09 00:00:00+00', NULL, '2026-08-09 00:00:00+00', NULL, 'JSON', '账号注销确认邮件模板', NULL, 'ACCOUNT_CANCELLED', true);
INSERT INTO public.sys_config (id, config_key, config_value, category, remark, sort_code, ext_json, created_at, created_by, updated_at, updated_by, value_type, label, scope, scene, is_builtin) VALUES ('cfg_mail_acct_purge_01', 'MAIL_TEMPLATE_ACCOUNT_PURGED', '{"subject": "{{app_name}} 账号已彻底删除", "body": "您好，您此前注销的账号已完成保留期清理，账号及相关个人数据已彻底删除。\n\n清理时间：{{purged_at}}\n感谢您曾使用 {{app_name}}。"}', 'MAIL_TEMPLATE', '账号彻底删除邮件模板', 21, '{}', '2026-08-09 00:00:00+00', NULL, '2026-08-09 00:00:00+00', NULL, 'JSON', '账号彻底删除邮件模板', NULL, 'ACCOUNT_PURGED', true);
INSERT INTO public.sys_config (id, config_key, config_value, category, remark, sort_code, ext_json, created_at, created_by, updated_at, updated_by, value_type, label, scope, scene, is_builtin) VALUES ('cfg_sms_acct_cancel_01', 'SMS_TEMPLATE_ACCOUNT_CANCELLED', '{"code": "", "content": "账号已申请注销，将于{{retention_days}}天后彻底删除。"}', 'SMS_TEMPLATE', '账号注销确认短信模板', 20, '{}', '2026-08-09 00:00:00+00', NULL, '2026-08-09 00:00:00+00', NULL, 'JSON', '账号注销确认短信模板', NULL, 'ACCOUNT_CANCELLED', true);
